(()=>{'use strict';const modes=['light','dark','glass'],safe=v=>modes.includes(v)?v:'light';let active='light';try{active=safe(localStorage.getItem('samandis-ui-theme'))}catch{}function apply(mode){active=safe(mode);document.documentElement.dataset.uiTheme=active;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',active==='dark'?'#14251f':active==='glass'?'#dfe5d5':'#e5e6d9');document.documentElement.style.colorScheme=active==='dark'?'dark':'light';document.querySelectorAll('[data-theme-choice]').forEach(b=>{const selected=b.dataset.themeChoice===active;b.setAttribute('aria-pressed',String(selected));b.classList.toggle('selected',selected)})}apply(active);function restore(){apply(window.SamandisPreferences?.get('appearance', 'light')||'light')}document.addEventListener('samandis-preferences-loaded',restore);function mount(){const panel=document.querySelector('#accountMorePanel');if(!panel||panel.querySelector('.appearance-menu'))return;const details=document.createElement('section');details.className='appearance-menu';details.innerHTML='<h3 class="appearance-title">حالت نمایش</h3><div class="appearance-choices">'+[['light','روشن','ساده و روشن'],['dark','تاریک','سرمه‌ای و آرام'],['glass','شیشه‌ای','شفاف و لطیف']].map(([id,label,desc])=>'<button type="button" data-theme-choice="'+id+'" aria-pressed="false"><span class="theme-swatch '+id+'" aria-hidden="true"><i></i><b></b><em></em></span><span><strong>'+label+'</strong><small>'+desc+'</small></span><span class="theme-choice-check" aria-hidden="true">✓</span></button>').join('')+'</div>';details.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=async()=>{const previous=active,mode=b.dataset.themeChoice;apply(mode);try{const shared=document.body.classList.contains('shared-app');if(shared&&typeof mine==='function'&&mine()&&window.SamandisPreferences)await SamandisPreferences.set('appearance',mode);localStorage.setItem('samandis-ui-theme',mode)}catch{apply(previous);if(typeof message==='function')message('ذخیرهٔ ظاهر برنامه انجام نشد؛ دوباره تلاش کنید.')}});panel.append(details);apply(active)}function start(){mount();const previous=render;render=function(...a){const r=previous(...a);mount();return r};if(window.SamandisPreferences&&typeof mine==='function'&&mine())restore()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start()})();
